actions.script:
                boolean ok = false
                Map result = null
                String message = null
                if (code && state && !error) {
                    try {
                        result = ec.service.sync().name('growerp.100.GoogleCalendarServices100.complete#GoogleSignIn')
                            .parameters([code: code, state: state]).call()
                        ok = !ec.message.hasError()
                    } catch (Throwable t) {
                        message = t.message
                    }
                    if (ec.message.hasError()) { message = ec.message.getErrorsString(); ec.message.clearErrors() }
                    // complete#GoogleSignIn acts as the user that started the sign in
                    if (ec.user.userId) ec.user.logoutUser()
                }
                String title = ok ? 'Google connected' : 'Google sign in failed'
                String body = ok ? "Connected${result?.email ? ' as ' + result.email : ''}. You can close this window and return to NASQO." :
                    "Google sign in did not complete${error ? ' (' + error + ')' : ''}. Close this window and try again."
                if (!ok && message) ec.logger.warn("Google sign in failed: ${message}")
                String html = """<!doctype html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title>
<style>body{font-family:sans-serif;display:flex;align-items:center;justify-content:center;height:100vh;margin:0;background:#f5f5f5}
div{background:#fff;padding:32px;border-radius:16px;max-width:420px;text-align:center;box-shadow:0 2px 8px rgba(0,0,0,.1)}</style>
</head><body><div><h2>${title}</h2><p>${org.moqui.util.StringUtilities.encodeForXmlAttribute(body)}</p></div>
<script>setTimeout(function(){window.close()},${ok ? 2000 : 8000})</script></body></html>"""
                ec.web.sendTextResponse(html, 'text/html', null)

ec.web.response.setHeader('Cache-Control', 'no-store')
ec.web.response.setHeader('Referrer-Policy', 'no-referrer')
try {
    def login = ec.resource.script(
        'component://growerp/service/NasqoGoogleLoginUtil.groovy', null)
    String authUrl = login.start(ec, (applicationId ?: 'AppAdmin').toString(), (intent ?: 'login').toString())
    ec.web.response.sendRedirect(authUrl)
} catch (Throwable t) {
    ec.logger.warn("NASQO Google login start refused: ${t.class.simpleName}")
    ec.web.response.sendRedirect('/?googleLogin=failed')
}

                ec.web.response.setHeader('Cache-Control', 'no-store')
                ec.web.response.setHeader('Referrer-Policy', 'no-referrer')
                String result = 'failed'
                if (code && state && !error) {
                    try {
                        def login = ec.resource.script(
                            'component://growerp/service/NasqoGoogleLoginUtil.groovy', null)
                        String outcome = login.complete(ec, (String)state, (String)code)
                        if (!ec.message.hasError() && outcome in ['success', 'registered']) {
                            result = outcome
                        }
                    } catch (Throwable t) {
                        // Never write the Google code or id_token to logs, errors or URLs.
                        ec.logger.warn("NASQO Google login callback refused: ${t.class.simpleName}")
                    }
                }
                if (ec.message.hasError()) ec.message.clearErrors()
                if (result == 'registered') {
                    ec.web.response.setHeader('X-Frame-Options', 'DENY')
                    ec.web.response.setHeader('Content-Security-Policy',
                        "default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'")
                    String html = '''<!doctype html><html lang="ar" dir="rtl"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>تم إنشاء حساب نسقو</title>
<style>body{font-family:sans-serif;background:#f5f8f8;color:#174a43;margin:0;
min-height:100vh;display:grid;place-items:center}main{background:white;padding:32px;
border-radius:16px;text-align:center;max-width:480px;box-shadow:0 3px 16px #0001}
a{display:inline-block;margin-top:20px;background:#167c6e;color:white;
padding:12px 24px;text-decoration:none;border-radius:8px}</style></head>
<body><main><h2>تم إنشاء حسابك في نسقو</h2>
<p>تم التحقق من حساب Google وإنشاء حساب نسقو. أكمل إعداد شركتك
واختيار الاشتراك من خلال تسجيل الدخول إلى النظام.</p>
<a href="/">الانتقال إلى نسقو ERP</a></main></body></html>'''
                    ec.web.sendTextResponse(html, 'text/html', null)
                } else {
                    ec.web.response.sendRedirect('/?googleLogin=' + result)
                }
